from collections import Counter

def period_stats(grid, p, interior=True):
    total=bad=0
    for r,row in enumerate(grid):
        if r<3: continue
        vals=[(c,v) for c,v in enumerate(row) if c>=3 and v not in (0,)]
        groups={}
        for c,v in vals: groups.setdefault(c%p,[]).append(v)
        for c,v in vals:
            total+=1
        for vs in groups.values(): bad+=len(vs)-max(Counter(vs).values())
    return bad,total, bad/total if total else 1
