def detect_period(grid):
    best=None
    for p in range(2,13):
        bad,total,_=period_stats(grid,p)
        rate=bad/total
        if rate < 0.03:
            return p
    # fallback by best normalized plus small complexity penalty
    return min(range(2,13), key=lambda p: period_stats(grid,p)[2]+0.001*p)

