    p=detect_period(grid)
    for r in range(3,h):
        groups={}
        for c in range(3,w):
            v=grid[r][c]
            if v:
                groups.setdefault(c%p,Counter())[v]+=1
        modes={k:cnt.most_common(1)[0][0] for k,cnt in groups.items()}
        # In this pattern every residue is seen somewhere along each row.
        for c in range(3,w):
            if out[r][c]==0 and c%p in modes:
                out[r][c]=modes[c%p]
    return out
