def _period(grid):
    h, w = len(grid), len(grid[0])
    total = sum(1 for r in range(3, h) for c in range(3, w) if grid[r][c] != 0)
    for p in range(2, 13):
        bad = 0
        for r in range(3, h):
            groups = {}
            for c in range(3, w):
                value = grid[r][c]
                if value:
                    groups.setdefault(c % p, Counter())[value] += 1
            bad += sum(sum(counts.values()) - max(counts.values()) for counts in groups.values())
        if total and bad / total < 0.03:
            return p
    return min(range(2, 13), key=lambda p: _error_rate(grid, p))

def _error_rate(grid, p):
    h, w = len(grid), len(grid[0])
    bad = total = 0
    for r in range(3, h):
        groups = {}
        for c in range(3, w):
            value = grid[r][c]
            if value:
                groups.setdefault(c % p, Counter())[value] += 1
        total += sum(sum(counts.values()) for counts in groups.values())
        bad += sum(sum(counts.values()) - max(counts.values()) for counts in groups.values())
    return bad / total + 0.001 * p if total else p

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Restore the background and the top/left frame where a mask covered them.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                if r < 2 or c < 2:
                    out[r][c] = 1
                elif r == 2 or c == 2:
                    out[r][c] = 4

    p = _period(grid)
    for r in range(3, h):
        groups = {}
        for c in range(3, w):
            value = grid[r][c]
            if value:
                groups.setdefault(c % p, Counter())[value] += 1
        modes = {residue: counts.most_common(1)[0][0]
                 for residue, counts in groups.items()}
        for c in range(3, w):
            if out[r][c] == 0 and c % p in modes:
                out[r][c] = modes[c % p]
    return out
